#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum NumpyObject {
    Int(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    /// Each element is (real, imag).
    ComplexArray(Vec<(f64, f64)>),
    Str(String),
    Bool(bool),
    /// Generic object without inherent scalar type information.
    Object,
}

/// Maps an object to its corresponding NumPy-like scalar data type.
/// The `default` is used only when `rep` is `NumpyObject::Object`.
pub fn obj2sctype(rep: NumpyObject, default: Option<NumpyScalarType>) -> Option<NumpyScalarType> {
    match rep {
        NumpyObject::Int(_) => Some(NumpyScalarType::Int64),
        NumpyObject::Float(_) => Some(NumpyScalarType::Float64),
        NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        NumpyObject::ComplexArray(_) => Some(NumpyScalarType::Complex128),
        NumpyObject::Str(_) => Some(NumpyScalarType::String),
        NumpyObject::Bool(_) => Some(NumpyScalarType::Bool),
        NumpyObject::Object => default,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn typed_scalars_ignore_default() {
        assert_eq!(obj2sctype(NumpyObject::Int(5), None), Some(NumpyScalarType::Int64));
        assert_eq!(
            obj2sctype(NumpyObject::Float(1.0), Some(NumpyScalarType::Int64)),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Str("x".to_string()), Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::String)
        );
        assert_eq!(
            obj2sctype(NumpyObject::Bool(true), Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Bool)
        );
    }

    #[test]
    fn arrays_map_to_element_types() {
        assert_eq!(
            obj2sctype(NumpyObject::IntArray(vec![1, 2]), None),
            Some(NumpyScalarType::Int64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::FloatArray(vec![1.0, 2.0]), None),
            Some(NumpyScalarType::Float64)
        );
        assert_eq!(
            obj2sctype(NumpyObject::ComplexArray(vec![(1.0, 2.0)]), None),
            Some(NumpyScalarType::Complex128)
        );
        // Empty arrays still have a known element type via the variant.
        assert_eq!(
            obj2sctype(NumpyObject::ComplexArray(vec![]), Some(NumpyScalarType::Int64)),
            Some(NumpyScalarType::Complex128)
        );
    }

    #[test]
    fn generic_object_uses_default_only() {
        assert_eq!(obj2sctype(NumpyObject::Object, None), None);
        assert_eq!(
            obj2sctype(NumpyObject::Object, Some(NumpyScalarType::Float64)),
            Some(NumpyScalarType::Float64)
        );
    }
}